 (0 = no limit; blank = site default).'=>'दिनदर्शिकेच्या प्रत्येक दिवशी दाखवले जाणारे कमाल कार्यक्रम (0 = मर्यादा नाही; रिकामे = साइट डीफॉल्ट).','Maximum File Size'=>'कमाल फाईल आकार','Maximum Files Per Upload'=>'प्रति अपलोड कमाल फाईल्स','Maximum Height (px)'=>'कमाल उंची (px)','Maximum Spaces Per Booking'=>'प्रति बुकिंग कमाल जागा','Maximum Width (px)'=>'कमाल रुंदी (px)','Maximum number of upcoming timeslots to show on initial page load. Enter 0 to show all upcoming timeslots.'=>'सुरुवातीला पान लोड होताना दाखवायच्या आगामी वेळ स्लॉटची कमाल संख्या. सर्व आगामी वेळ स्लॉट दाखवण्यासाठी 0 टाका.','Maximum of %d files are allowed.'=>'जास्तीत जास्त %d फाईलना परवानगी आहे.','Maximum size (bytes)'=>'कमाल आकार (बाइट्स)','Maximum spaces per booking'=>'प्रति बुकिंग कमाल जागा','Maybe'=>'कदाचित','Maybe Attending'=>'कदाचित उपस्थित','Medium'=>'मध्यम','Metric'=>'मेट्रिक','Metrics'=>'मेट्रिक्स','Migrate'=>'स्थलांतर करा','Migrate Formats'=>'फॉरमॅट स्थलांतरित करा','Migrate from %s'=>'%s मधून स्थलांतर करा','Migrate tickets, RSVPs and attendees'=>'तिकिटे, RSVP आणि उपस्थित स्थलांतरित करा','Migrate to Events Manager'=>'Events Manager मध्ये स्थलांतर करा','Miles'=>'मैल','Min'=>'किमान','Min/Max'=>'किमान/कमाल','Minimum Height (px)'=>'किमान उंची (px)','Minimum Width (px)'=>'किमान रुंदी (px)','Minutes'=>'मिनिटे','Minutes before the event'=>'कार्यक्रमाच्या आधीची मिनिटे','Missing fields: '=>'अनुपस्थित फील्ड: ','Missing required field: %s'=>'आवश्यक फील्ड गहाळ आहे: %s','Mobile App Notifications'=>'मोबाइल अॅप सूचना','Modal'=>'मोडल','Modal Popup'=>'मॉडल पॉपअप','Modifications to %s can be applied to all recurrences and will overwrite any changes made to those individual %s recurrences.'=>'%s मधील बदल सर्व आवर्तनांना लागू केले जाऊ शकतात आणि त्या वैयक्तिक %s आवर्तनांमध्ये केलेले कोणतेही बदल अधिलिखित करतील.','Modifications to event tickets will cause all bookings to individual recurrences of this event to be deleted.'=>'कार्यक्रम तिकिटांमधील बदलांमुळे या कार्यक्रमाच्या वैयक्तिक आवर्तनांचे सर्व बुकिंग हटवले जातील.','Modifications to repeating events will be applied to all recurrences and will overwrite any changes made to those individual event recurrences.'=>'आवर्ती कार्यक्रमांमधील बदल सर्व आवर्तनांना लागू केले जातील आणि त्या वैयक्तिक कार्यक्रम आवर्तनांमध्ये केलेले कोणतेही बदल अधिलिखित करतील.','Modified unavailable dates.'=>'अनुपलब्ध तारखा बदलल्या.','Modify Booking'=>'बुकिंग बदला','Modify Recurring Event Tickets '=>'आवर्ती कार्यक्रमाची तिकिटे बदला ','Modify Unavailable Dates?'=>'अनुपलब्ध तारखा बदलायच्या?','Modify what information is displayed in this booking table.'=>'या बुकिंग टेबलमध्ये कोणती माहिती दाखवली जाते ते बदला.','Month first: 03/04/2027 is March 4'=>'आधी महिना: 03/04/2027 म्हणजे 4 मार्च','Month format'=>'महिना स्वरूप','Monthly'=>'मासिक','More Events message'=>'अधिक कार्यक्रम संदेश','More Info'=>'अधिक माहिती','More information about migrating to v6 can be found %s.'=>'V6 वर स्थलांतर करण्याबद्दल अधिक माहिती %s येथे मिळेल.','Most of an event held at once (%)'=>'एकाच वेळी राखून ठेवलेला कार्यक्रमाचा कमाल भाग (%)','Moving from %s?'=>'%s मधून येत आहात?','Multi Line'=>'अनेक ओळी','Multi Site Options'=>'मल्टी साइट पर्याय','MultiSite options have moved <a href="%s">here</a>. <a href="%s">Dismiss message</a>'=>'मल्टीसाइट पर्याय <a href="%s">येथे</a> हलवले आहेत. <a href="%s">संदेश घालवा</a>','Multiple Timeslots'=>'एकाधिक टाइमस्लॉट','Multiple dots'=>'अनेक ठिपके','Multiple file uploads are not allowed'=>'एकापेक्षा जास्त फाईल अपलोड करण्याची परवानगी नाही','Multisite Settings'=>'मल्टीसाईट सेटिंग्स','My %s'=>'माझे %s','My Bookings'=>'माझी बुकिंग','My Bookings messages'=>'माझी बुकिंग संदेश','My Event Bookings'=>'माझ्या कार्यक्रमांची बुकिंग','My Events'=>'माझे कार्यक्रम','My Locations'=>'माझी स्थाने','My Profile'=>'माझी प्रोफाईल','My bookings'=>'माझी बुकिंग','My bookings page'=>'माझे बुकिंग पृष्ठ','N/A'=>'लागू नाही','Name'=>'नाव','Name: %s'=>'नाव: %s','Near...'=>'जवळ...','Need event-specific cancellation settings or support for hours after an event started? This is included in our %